    Halide::Buffer<num_t, 1> B(n);

    // Initialize A and B.
    init_array(n, A, B);

    // ImageParams to bind A and B for the stencil steps.
    ImageParam A_param(type_of<num_t>(), 1, "A_param");
    ImageParam B_param(type_of<num_t>(), 1, "B_param");

    Var i("i");

    // Clamp A and B so that neighbor accesses (i-1, i+1) are always in-bounds.
    Func A_clamped("A_clamped"), B_clamped("B_clamped");
    // extent() is the runtime length; clamp keeps indices within [0, extent-1].
    A_clamped(i) = A_param(clamp(i, 0, A_param.dim(0).extent() - 1));
    B_clamped(i) = B_param(clamp(i, 0, B_param.dim(0).extent() - 1));

    // One Jacobi half-step: A -> B
    //
    // for (i = 1; i < n - 1; i++)
    //   B[i] = 0.33333 * (A[i-1] + A[i] + A[i+1]);
    //
    // i == 0 and i == n-1 are left unchanged.
