#include <chrono>
#include <iomanip>
#include <iostream>

#include "Halide.h"

// include common PolyBench-style definitions (DATA_TYPE, N, TSTEPS, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for jacobi-1d (N, TSTEPS)
#include "jacobi-1d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Initialize arrays A and B.
 *
 * Original C:
 *   for (i = 0; i < n; i++) {
 *     A[i] = ((DATA_TYPE) i + 2) / n;
 *     B[i] = ((DATA_TYPE) i + 3) / n;
 *   }
 *
 * Here we implement the same initialization using Halide Funcs.
 */
static void init_array(int n,
                       Halide::Buffer<num_t, 1> A,
                       Halide::Buffer<num_t, 1> B) {
    Var i("i");
    Func init_A("init_A"), init_B("init_B");

    // Cast to num_t to ensure floating-point division when DATA_TYPE is float/double.
    init_A(i) = (cast<num_t>(i) + (num_t)2) / (num_t)n;
    init_B(i) = (cast<num_t>(i) + (num_t)3) / (num_t)n;

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
    // Problem size and time steps from PolyBench-style headers.
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate input/output buffers.
    // A will be updated in-place across time steps.
    // B will hold the initial B; only its endpoints B[0] and B[n-1] are
    // actually used by the Jacobi scheme (interior is overwritten every step).
    Halide::Buffer<num_t, 1> A(n);
    Halide::Buffer<num_t, 1> B(n);

    // Initialize A and B.
    init_array(n, A, B);

    // Halide representation of one full Jacobi time step:
    //
    // Original C kernel (per time step t):
    //
    //   for (i = 1; i < n - 1; i++)
    //       B[i] = 0.33333 * (A[i-1] + A[i] + A[i + 1]);
    //   for (i = 1; i < n - 1; i++)
    //       A[i] = 0.33333 * (B[i-1] + B[i] + B[i + 1]);
    //
    // A[0], A[n-1], B[0], and B[n-1] are never updated.
    //
    // Observations:
    // - B interior is recomputed every time step from the current A.
    //   Its previous interior values are not used across time steps.
    // - B[0] and B[n-1] remain constant and are used as fixed boundary
    //   values in the second loop.
    // - A[0] and A[n-1] remain constant across time.
    //
    // We express one time step as a Halide pipeline:
    //   A_prev -> (compute interior B from A_prev) -> B_full (with fixed endpoints)
    //          -> compute interior A_next from B_full.
    //
    // The time dimension is driven from the host using a for-loop and
    // double-buffering (rule 5 in the instructions).

    // Parameters and ImageParams used in the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 1, "A_param");       // current A
    ImageParam B_bound_param(type_of<num_t>(), 1, "B_bound"); // fixed B boundary (endpoints)
    Param<int> n_param("n");                                  // array length

    Var i("i");

    // Constant coefficient 0.33333 as num_t.
    const num_t one_third_val = (num_t)0.33333;

    // Clamp A indices to stay within [0, n_param-1].
    // This makes neighbor accesses safe at the boundaries.
    Func A_clamped("A_clamped");
    A_clamped(i) = A_param(clamp(i, 0, n_param - 1));

    // First pass: compute an intermediate B_temp from A_clamped.
    //
    // B_temp(i) = 1/3 * (A[i-1] + A[i] + A[i+1]), for all i.
    // We'll later combine B_temp's interior with the fixed endpoints from B.
    Func B_temp("B_temp");
    B_temp(i) = one_third_val *
                (A_clamped(i - 1) + A_clamped(i) + A_clamped(i + 1));

    // Construct B_full(i) which matches the semantics of the original B array:
    // - At i == 0 or i == n-1, use the original B endpoints (B_bound_param).
    // - At interior points, use B_temp.
    //
    // We clamp the index for B_bound_param to avoid any potential out-of-bounds
    // (Halide's bounds inference does not treat select() as a guard).
    Func B_full("B_full");
    B_full(i) = select(
        (i == 0) || (i == n_param - 1),
        B_bound_param(clamp(i, 0, n_param - 1)),  // use fixed B endpoints
        B_temp(i)                                  // interior from first pass
    );

    // Second pass: compute A_next from B_full.
    //
    // For interior points, this is a 3-point stencil on B_full.
    // For endpoints, just preserve the previous A values.
    Func A_next("A_next");
    A_next(i) = select(
        (i == 0) || (i == n_param - 1),
        A_param(i),  // keep boundaries fixed
        one_third_val * (B_full(i - 1) + B_full(i) + B_full(i + 1))
    );

    // Simple schedule: rely on Halide's default scheduling, which will inline
    // A_clamped, B_temp, and B_full into A_next and compute A_next at root.
    // This preserves the basic structure of the original 1D loop.
    //
    // A_next.compile_jit() will be called below.

    // Bind constant parameters that don't change across time steps.
    n_param.set(n);
    B_bound_param.set(B);

    // JIT-compile the pipeline once.
    A_next.compile_jit();

    // Buffer used to hold the newly computed A for each time step.
    Halide::Buffer<num_t, 1> A_new(n);

    // Measure execution time of the time-stepping loop.
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tsteps; t++) {
        // Bind the current state of A to the ImageParam.
        A_param.set(A);

        // Compute the next state into A_new.
        A_next.realize(A_new);

        // Swap buffers so that A always holds the current state.
        std::swap(A, A_new);
    }

    auto end      = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting array A to stderr (to prevent dead-code
    // elimination in analogy with the PolyBench DCE printing).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int idx = 0; idx < n; idx++) {
            if (idx % 20 == 0) {
                std::cerr << '\n';
            }
            std::cerr << A(idx);
        }
        std::cerr << '\n';
    }

    // Print the elapsed time in seconds with 6 decimal places.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
