#include "defines.hpp"

// Benchmark-specific definitions for jacobi-1d (N, TSTEPS)
#include "jacobi-1d.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize arrays A and B as in the original C code:
//
// for (i = 0; i < n; i++) {
//   A[i] = ((DATA_TYPE)i + 2) / n;
//   B[i] = ((DATA_TYPE)i + 3) / n;
// }
static void init_array(int n,
                       Halide::Buffer<num_t, 1> A,
                       Halide::Buffer<num_t, 1> B) {
    Var i("i");
    Func init_A("init_A"), init_B("init_B");

    // A[i] = (i + 2) / n;
    init_A(i) = (cast<num_t>(i + 2)) / cast<num_t>(n);

    // B[i] = (i + 3) / n;
    init_B(i) = (cast<num_t>(i + 3)) / cast<num_t>(n);

    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char **argv) {
    // Problem size and number of time steps.
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate 1D arrays A and B.
    // The Polybench C version uses A[N], B[N].
    Halide::Buffer<num_t, 1> A(n);
    Halide::Buffer<num_t, 1> B(n);

    // Initialize arrays.
    init_array(n, A, B);

    // Halide ImageParams to wrap A and B for the Jacobi steps.
    ImageParam A_param(type_of<num_t>(), 1, "A_param");
    ImageParam B_param(type_of<num_t>(), 1, "B_param");

    // Define the Jacobi 1D update steps.
    //
    // Original kernel:
    //
    // for (t = 0; t < tsteps; t++) {
    //   for (i = 1; i < n-1; i++)
    //     B[i] = 0.33333 * (A[i-1] + A[i] + A[i+1]);
    //   for (i = 1; i < n-1; i++)
    //     A[i] = 0.33333 * (B[i-1] + B[i] + B[i+1]);
    // }
    //
    // We implement each of the two inner loops as a separate Halide Func
    // that computes the interior points [1, n-2]. To avoid out-of-bounds
    // accesses and to match the original loop bounds exactly, we realize
    // these Funcs over indices 0..(n-3), and then copy them into
    // positions 1..(n-2) in A and B, leaving the boundaries untouched.

    Var i("i");

    Func jacobi_B("jacobi_B");
    // Computes values for B[1..n-2] based on A.
    // We map: i_halide in [0..n-3] -> A[i_halide], A[i_halide+1], A[i_halide+2]
    // which correspond to A[0..n-1] and are always in-bounds.
    jacobi_B(i) = (A_param(i) + A_param(i + 1) + A_param(i + 2)) / cast<num_t>(3);

    Func jacobi_A("jacobi_A");
    // Computes values for A[1..n-2] based on B.
    jacobi_A(i) = (B_param(i) + B_param(i + 1) + B_param(i + 2)) / cast<num_t>(3);

    // Simple schedules: just compute over i in the default order.
    // (No explicit reordering or tiling is necessary for a 1D stencil.)
    jacobi_B.compute_root();
    jacobi_A.compute_root();

    // Bind the initial buffers so we can JIT-compile before timing.
    A_param.set(A);
    B_param.set(B);

    jacobi_B.compile_jit();
    jacobi_A.compile_jit();

    // Temporary buffers for interior results (size n-2).
    Halide::Buffer<num_t, 1> B_interior(n - 2);
    Halide::Buffer<num_t, 1> A_interior(n - 2);

    // Time the main Jacobi kernel (tsteps time iterations).
    auto start = std::chrono::high_resolution_clock::now();

    for (int t = 0; t < tsteps; t++) {
        // Step 1: update B from A for interior points.
        // B[i] = (A[i-1] + A[i] + A[i+1]) / 3, for i in 1..n-2.
        A_param.set(A);
        jacobi_B.realize(B_interior);

        for (int idx = 0; idx < n - 2; idx++) {
            int i_real = idx + 1;  // interior index in [1..n-2]
            B(i_real) = B_interior(idx);
        }
        // B[0] and B[n-1] remain unchanged, exactly as in the original code.

        // Step 2: update A from B for interior points.
        // A[i] = (B[i-1] + B[i] + B[i+1]) / 3, for i in 1..n-2.
        B_param.set(B);
        jacobi_A.realize(A_interior);

        for (int idx = 0; idx < n - 2; idx++) {
            int i_real = idx + 1;  // interior index in [1..n-2]
            A(i_real) = A_interior(idx);
        }
        // A[0] and A[n-1] remain unchanged.
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result (to mimic the Polybench print_array
    // and to prevent dead-code elimination).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(6);
        for (int i_out = 0; i_out < n; i_out++) {
            std::cerr << A(i_out) << '\n';
        }
    }

    // Print the elapsed time in seconds with microsecond resolution.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
